      "pitch": "This work proposes an adaptation of the Facility Location Problem for the optimal placement of on-orbit servicing depots for satellite constellations in high-altitude orbit. The high-altitude regime, such as Medium Earth Orbit (MEO), is a unique dynamical environment where existing low-thrust propulsion systems can provide the necessary thrust to conduct plane-change maneuvers between the various orbital planes of the constellation.\n\n[facility location · facility location problem]"
