      "pitch": "We show that\nthe best non-preemptive schedule (where a package that is picked up at its\nsource is immediately delivered to its destination by one drone) is within\na factor of three of the best preemptive schedule (where several drones\ncan participate in the delivery of a single package). Then, we present\na constant-factor approximation algorithm for the problem of computing\nthe best non-preemptive schedule.\n\n[approximation algorithm]"
