      "pitch": "1\nGSW: Generalized “Self-Wiener” Denoising\nAmir Weiss\nFaculty of Engineering\nBar-Ilan University\nRamat-Gan, Israel\namir.weiss@biu.ac.il\nAbstract—We revisit the recently proposed “self-Wiener” (SW)\nfiltering method for robust deconvolution, and generalize it\nto the classical denoising problem. The resulting estimator,\ntermed generalized SW (GSW) filtering, retains the nonlinear\nshrinkage structure of SW but introduces a tunable threshold\nparameter.\n\n[Filter · Fourier transform]"
