      "pitch": "However, conventional\napproaches based on finite abstractions often incur prohibitive\ncomputational costs as the number of agents and the complexity\nof temporal logic specifications increase. In this work, we study\nhomogeneous stochastic MAS under counting linear temporal\nlogic (cLTL) specifications, and show that the corresponding\nsatisfaction probability admits a structured tensor decomposition\nvia leveraging deterministic finite automata (DFA).\n\n[dynamic programming]"
