      "pitch": "This paper considers the\nproblem of selecting the optimal input matrix for a linear\nsystem that maximizes warping of the reachable set along a\ndirection of interest. The main result establishes that under\ncertain assumptions on the dynamics, the problem reduces to\na finite number of linear optimization problems.\n\n[Convex optimization]"
