      "novelty_bits": 9.1,
      "novelty_breakdown": {
        "concept_bits": 7.6,
        "edge_bits": 0.0,
        "new_term_bonus": 1.5
      },
      "pitch": "We present an overview of key properties of Lambert series generating function expansions, their more combinatorial generalizations, and include a compendia of tables illustrating known formulas for special cases of these series. In this sense, we focus more on the formal properties of the sequences that are enumerated by the Lambert series, and do not spend significant time treating these series as analytic objects subject to rigorous convergence constraints.\n\n[partition function · Partition]"
